custom_css:
/*
主题：水色卡片
作者：discord@无
发布于lc、wbz，可二改。二传什么的还是不要了吧！
感恩旅程墨千尾老师的美化教程，感恩补充撰写拼好码的老师们，感恩小红书的毛毛雨老师，感恩gemini，感恩一切……
水色卡片这版改动幅度比较大，让gemini回炉重造了很多次，所以很多代码已经面目全非了……来源我会尽力标注。
*/

/* 先导篇：字体导入 */
@import url("https://fontsapi.zeoseven.com/309/main/result.css");

body {
    font-family: "KingHwaOldSong";
    font-weight: normal;
}

/* === 一、全局控制 === */
:root {
  --字体1: 'KingHwaOldSong';
  --自定义思维链文案: "Thinking...";
  --自定义“加载更多信息”文案: "加载更早的消息";
  --自定义输入框文字: "写给你的情诗...";

  /* --- 灰蓝调色盘 --- */
  --ins-bg: #ffffff;      
  --ins-card: rgba(255, 255, 255, 0.55);  /* 毛玻璃卡片底色：半透明白 */
  --ins-accent: #7d8ba4;  
  --ins-border: #d9e2ec;  
}
:root {
  /* --- 底部堆叠装饰图变量 --- */
  --bot-img-1: url('https://img.heliar.top/file/1776531680452_IMG_4476.png'); /* 上层图片 */
  --bot-img-2: url('https://img.heliar.top/file/1776531326159_IMG_4475.png'); /* 下层图片 */
}

body {
  font-family: var(--字体1);
  background-color: var(--ins-bg) !important;
}

/* === 二、聊天区域 === */

/* 1. 聊天区域全局背景 (保持透明) */
#chat {
  background-color: transparent !important; 
  padding-left: 10px !important;
  padding-right: 10px !important;
}

/* 2. 聊天气泡主体 (毛玻璃质感) */
.mes {
    display: flex; 
    flex-direction: column !important;
    align-items: flex-start; 
    max-width: 98% !important; 
    margin-left: auto !important;
    margin-right: auto !important;

    /* 核心样式：毛玻璃 (半透明 + 模糊叠加) */
    background: var(--ins-card) !important;
    backdrop-filter: blur(12px) !important;
    -webkit-backdrop-filter: blur(12px) !important; 

    border: 1px solid rgba(255, 255, 255, 0.5) !important;
    box-shadow: 2px 4px 12px rgba(164, 176, 196, 0.1) !important;

    border-radius: 8px !important; 
    padding: 25px 20px 20px 20px !important; 
    margin-top: 70px !important;
    margin-bottom: 45px !important; 
    gap: 12px;
    position: relative !important;
    overflow: visible !important;
}

/* 3. 气泡上方背景图 */
:root {
  --char-top-bg: url('https://img.heliar.top/file/1776501439633_IMG_4464.jpeg');
  --user-top-bg: url('https://img.heliar.top/file/1776500326947_IMG_4459.jpeg');

  --card-blue-light: rgba(230, 240, 250, 0.6); /* 半透明浅蓝 */
  --card-blue-accent: #a4b0c4; 
  --card-shadow: rgba(164, 176, 196, 0.15); 
}

.mes::before {
    content: '';
    position: absolute;
    top: -56px; 
    left: 0;
    width: 100%;
    height: 45px; 
    background-size: cover;
    background-position: center;
    border-radius: 8px 8px 0 0; 
    z-index: 1;
    opacity: 0.8;
    box-shadow: 0 2px 6px var(--card-shadow);
    border: 1px solid rgba(255, 255, 255, 0.6);
    border-bottom: none; 
}

.mes[is_user="false"]::before { background-image: var(--char-top-bg); }
.mes[is_user="true"]::before { background-image: var(--user-top-bg); }

/* --- 气泡下方双图堆叠装饰 --- */
.mes::after {
    content: '';
    position: absolute;
    bottom: -58px; /* 控制装饰图在气泡下方的位置，数值取决于图片高度 */
    left: 0;
    width: 100%;
    height: 80px; /* 装饰区域的整体高度 */

    background-image: var(--bot-img-1), var(--bot-img-2);
    background-size: contain, contain;
    background-position: right 55px bottom 15px, right 0px bottom 0px; 
    background-repeat: no-repeat, no-repeat;
    border-radius: 0 0 8px 8px; 
    z-index: 1;
    opacity: 0.75;
    pointer-events: none;
}

/* 4. 头像和名称排版 */
.mes .mesAvatarWrapper {
    display: inline-flex !important;
    flex-direction: row !important;
    align-items: center !important;
    justify-content: flex-start !important;
    gap: 10px !important;

    background: var(--card-blue-light) !important;
    backdrop-filter: blur(8px) !important;
    -webkit-backdrop-filter: blur(8px) !important;
    border: 1px solid rgba(255, 255, 255, 0.6) !important;
    box-shadow: 0 2px 6px var(--card-shadow) !important; 
    border-radius: 50px !important; 

    padding: 4px 16px 4px 4px !important;
    width: max-content !important;
    max-width: calc(100% - 30px) !important; 

    margin-top: -44px !important; 
    margin-left: -15px !important; 
    margin-bottom: 10px !important; 

    position: relative !important;
    z-index: 10 !important; 
    flex-wrap: nowrap !important;
    pointer-events: none !important;
}

.mes .avatar,
.mes .ch_name,
.mes .mes_time {
    pointer-events: auto !important; 
}
.mes .ch_name {
    color: var(--card-blue-accent) !important; 
    font-weight: bold !important;
    text-shadow: none !important;
}
.mes .mes_time {
    color: #a4b0c4 !important;
    font-size: 0.85em !important;
    margin-left: auto; 
}

/* 5. 头像框扁平化 */
.mes .avatar {
    width: 40px !important; 
    height: 40px !important;
    position: relative !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    flex-shrink: 0 !important;
    border-radius: 50% !important;
    box-shadow: 0 2px 6px var(--card-shadow) !important;
    background: rgba(255, 255, 255, 0.8) !important;
}

.mes .avatar img {
    width: calc(100% - 4px) !important;
    height: calc(100% - 4px) !important;
    outline: none !important; 
    border-radius: 50% !important;
    object-fit: cover !important; 
    border: none !important; 
}

.mes .avatar::after {
    content: '' !important;
    position: absolute !important;
    inset: 0 !important;
    border-radius: 50% !important;    
    border: 2px solid rgba(255, 255, 255, 0.8) !important;
    pointer-events: none !important;
    z-index: 2 !important; 
}
.mes .avatar::before { display: none !important; }
.mes.last_mes .mesAvatarWrapper { padding-bottom: 4px !important; }

/* 6. 正文格式 */
.mes .mes_text {
  padding: 0px !important; 
  width: 100% !important; 
  text-align: justify !important;
  line-height: 1.8;
  position: relative !important; 
  overflow: visible !important;
}

/* 7. 引用与代码块修饰 */
.mes_text q {
    background-color: var(--card-blue-light);
    border-bottom: none;
    border-left: 3px solid var(--card-blue-accent);
    margin: 12px 0;
    padding: 6px 12px;
    border-radius: 4px 8px 8px 4px; 
    font-style: normal;
    box-shadow: none;
}
blockquote {
    background: var(--card-blue-light) !important;
    border-left: 3px solid var(--card-blue-accent) !important;
    border-radius: 4px 8px 8px 4px !important;
    padding: 8px 12px !important;
    margin: 8px auto !important;
}
code {
    background: var(--card-blue-light) !important;
    border-radius: 4px;
    color: var(--card-blue-accent);
    padding: 2px 6px !important;
}

/* === 三、顶栏 === */

#top-settings-holder .drawer-icon::before {
  content: "" !important;
  display: none !important;
}

#top-settings-holder .drawer-icon {
  background-size: contain !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  width: 24px !important; 
  height: 24px !important;
  opacity: 1;
  transition: transform 0.2s ease-in-out, filter 0.2s ease-in-out;
  display: inline-block !important; 
}

#ai-config-button .drawer-icon { background-image: url('https://img.heliar.top/file/1776315252713_IMG_4374.png') !important; }
#advanced-formatting-button .drawer-icon { background-image: url('https://img.heliar.top/file/1776314679436_IMG_4371.png') !important; }
#user-settings-button .drawer-icon { background-image: url('https://img.heliar.top/file/1776309392800_IMG_4362.png') !important; }
#extensions-settings-button .drawer-icon { background-image: url('https://img.heliar.top/file/1776310712150_IMG_4365.png') !important; }
#persona-management-button .drawer-icon { background-image: url('https://img.heliar.top/file/1776312060069_IMG_4367.png') !important; }
#sys-settings-button .drawer-icon { background-image: url('https://img.heliar.top/file/1776310719184_IMG_4364.png') !important; }
#WI-SP-button .drawer-icon { background-image: url('https://img.heliar.top/file/1776313779230_IMG_4368.png') !important; }
#backgrounds-drawer-toggle .drawer-icon { background-image: url('https://img.heliar.top/file/1776309404202_IMG_4356.png') !important; }
#rightNavHolder .drawer-icon { background-image: url('https://img.heliar.top/file/1776310990722_IMG_4366.png') !important; }
#gaigai-top-btn { background-image: url('https://img.heliar.top/file/1776315046083_IMG_4373.png') !important; }
#horae_drawer_icon { background-image: url('https://img.heliar.top/file/1776315046083_IMG_4373.png') !important; }
#table_drawer_icon.drawer-icon { background-image: url('https://img.heliar.top/file/1776315046083_IMG_4373.png') !important; }
#table_database_settings_drawer-icon { background-image: url('https://img.heliar.top/file/1776315046083_IMG_4373.png') !important; }

#top-settings-holder .drawer-icon:hover { transform: scale(1.1); }

/* 底栏文字 感谢墨千尾老师 */
#send_textarea::placeholder {
    color: transparent !important; 
    text-shadow: none !important;
}
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: var(--自定义输入框文字);
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    font-size: 0.5em;
    pointer-events: none;
    z-index: 10;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: calc(100% - 30px);
    color: rgba(175, 175, 175, 1);
    font-style: italic;
}

#nonQRFormItems { margin: 5px 5px; }

#send_form [class*="fa-"]::before {
  font-size: 20px; 
  color: var(--ins-accent) !important;
  transition: color 0.2s;
}
#send_form [class*="fa-"]:hover::before { color: #7f7f7f !important; }

/* === 五、全局弹出面板 === */
.drawer-content, 
#table_drawer_content, 
.options-content {
  background-color: rgba(255, 255, 255, 0.8) !important;
  backdrop-filter: blur(10px);
  border-color: #ffffff;
}

* {
    filter: none !important;
    outline: none !important;
    box-shadow: none !important;
}

::-webkit-scrollbar {
    width: 6px; 
    height: 6px; 
    background-color: transparent; 
}
::-webkit-scrollbar-track { background-color: transparent; }
::-webkit-scrollbar-thumb {
    background-color: var(--ins-border);
    border-radius: 10px;
    border: none; 
}

input[type='checkbox'] {
    appearance: none !important;
    -webkit-appearance: none !important;
    width: 20px !important;
    height: 20px !important;
    border-radius: 6px !important;
    margin: 3px 0px;
    vertical-align: middle;
    background: #ffffff !important;
    border: 2px solid #A4B0C4 !important;
    box-shadow: none !important;
    transition: all 0.2s ease !important;
    position: relative;
    cursor: pointer;
}
input[type='checkbox']:hover { border-color: #A4B0C4 !important; }
input[type='checkbox']:checked {
    background: #A4B0C4 !important;
    border-color: #A4B0C4!important;
    box-shadow: none !important;
}

input[type="radio"] {
    appearance: none !important;
    -webkit-appearance: none !important;
    width: 20px !important;
    height: 20px !important;
    margin: 3px 0px;
    border-radius: 50% !important;
    background: #ffffff !important;
    border: 2px solid #A4B0C4 !important;
    box-shadow: none !important;
    transition: all 0.2s ease !important;
    position: relative;
    cursor: pointer;
}
input[type="radio"]:hover { border-color: #A4B0C4 !important; }
input[type="radio"]:checked {
    border: 6px solid #A4B0C4 !important;
    background: #ffffff !important;
    box-shadow: none !important;
}

input[type=range] {
    height: 24px !important; 
    background: none !important;
    border: none !important;
    box-shadow: none !important;
    width: 100% !important;
    cursor: pointer;
}
input[type=range]::-webkit-slider-runnable-track {
    height: 6px;
    background: #e8eaed !important;
    border: none !important;
    border-radius: 4px;
    box-shadow: none !important;
}
input[type="range"]::-webkit-slider-thumb {
    width: 18px;
    height: 18px;
    border-radius: 50% !important;
    border: 2px solid #ffffff !important;
    background: #A4B0C4 !important;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.15) !important; 
    margin-top: -6px !important;
    transition: transform 0.1s;
}
input[type="range"]::-webkit-slider-thumb:hover { transform: scale(1.15); }

.inline-drawer-content,
#wiActivationSettings,
#wiSliders {
    background: none !important;
    padding: 0px;
}

strong::before, b::before, h4:not(.margin0) span::before, #persona-management-button.drawer .standoutHeader::before { margin-right: 6px; }

#extensions_settings .inline-drawer-toggle.inline-drawer-header, #extensions_settings2 .inline-drawer-toggle.inline-drawer-header, #user-settings-block h4, .standoutHeader, .inline-drawer-header {
  border: none;
  background-image: none !important;
  font-weight: normal !important;
  font-size: 1em;
  border-radius: 12px 12px 12px 12px;
  background-color: rgba(125, 139, 164, 0.06);
  border-bottom: 2px solid #c0cee5;
  box-shadow: 2px 2px 12px rgba(0, 0, 0, 0.015);
  line-height: 1.7;
  padding: 6px 6px;
}

:is(.select2-container--default .select2-selection--single, .text_pole, select, .text_input, textarea:not(#send_textarea)) {
    background: #fff !important;
    border: 1px solid rgb(220 220 220 / 0.5) !important;
    border-radius: 10px !important;
    box-shadow: unset !important;
}
input[type=number] {
    background: #fff !important;
    border: 1px solid rgb(220 220 220 / 0.5) !important;
    border-radius: 8px !important;
}
.inline-drawer-content { background: transparent !important }

#completion_prompt_manager_list { padding: 8px !important; }
.completion_prompt_manager_header, .prompt-manager-inspect-action { color: #5a5a5a !important; }
.completion_prompt_manager_prompt {
    overflow: visible !important;
    padding: 7px 15px !important;
    margin: 3px 0 !important;
    background: none !important;
    border: none !important;
    border-radius: 8px !important;
    transition: all 0.2s !important;
}
.completion_prompt_manager_prompt_disabled { opacity: 0.3; }
.completion_prompt_manager_prompt:hover {
    background: white !important;
    padding-left: 24px !important;
}

.avatar-container {
    transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1) !important;
    border-radius: 14px !important; 
    background: #ffffff !important;
    border: 1.6px solid transparent !important;
    box-shadow: 0 2px 8px rgba(0,0,0,0.02) !important;
    padding: 6px !important;
    margin: 0px !important; 
    opacity: 0.6; 
    cursor: pointer;
}
.avatar-container.selected {
    opacity: 1;
    transform: translateY(-4px) !important;
    border-color: #A4B0C4 !important;
    box-shadow: 0 8px 16px rgba(138, 180, 248, 0.15) !important;
}

#toast-container > .toast {
    top: 30px !important;
    margin: 10px auto !important;
    width: 80% !important;
    max-width: 400px !important;
    min-height: auto;
    background-image: none !important;
    background-color: rgba(255, 255, 255, 0.4) !important;
    backdrop-filter: blur(13px); 
    -webkit-backdrop-filter: blur(10px);
    border: 1px solid #e8eaed !important;
    border-radius: 16px !important;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.05) !important; 
    color: #abaaaa !important;
    padding: 16px 24px !important;
    transition: all 0.3s ease;
}
.toast-title {
    color: #A4B0C4 !important;
    letter-spacing: 0.5px;
    border-bottom: none !important; 
    padding-bottom: 0px;
    margin-bottom: 6px !important;
    font-weight: 600 !important;
    font-size: 15px;
}

/* === 六、正则+脚本易读+防误触 === */
#saved_regex_scripts, #saved_scoped_scripts, #saved_preset_scripts, #global-script-list, #character-script-list {
  margin-right: 80px !important;
}

.regex-script-label.flex-container, .flex-container .script-item {
  flex-wrap: wrap !important;
  padding: 10px 14px; 
  border-radius: 10px; 
  margin-bottom: 8px; 
  background: rgba(255, 255, 255, 0.6); 
  border: 1px solid var(--ins-border); 
}
.regex-script-label.flex-container .regex_script_name, .script-item .script-item-name {
  flex-basis: 100%;
  word-break: break-word; 
  font-weight: 500;
  font-size: 14px;
  color: #7f7f7f;
}

/* === 七、“加载更多消息”美化 === */
#show_more_messages {
  font-size: 0 !important;
  color: transparent !important; 
  display: block;
  padding: 8px 24px;
  margin: 20px auto; 
  width: fit-content; 
  background-color: transparent; 
  border: 1px solid var(--ins-border); 
  border-radius: 30px; 
  box-shadow: none; 
  cursor: pointer;
  transition: all 0.3s ease;
}
#show_more_messages::before {
  content: var(--自定义“加载更多信息”文案); 
  font-size: 12px !important; 
  color: var(--ins-accent) !important; 
  font-weight: 500;
}
#show_more_messages:hover { background-color: var(--ins-border); }
#show_more_messages:hover::before { color: #7f7f7f !important; }

/* === 八、思维链美化 === */
.mes_reasoning_summary {
  list-style: none; 
  cursor: pointer;
  display: flex !important;
  align-items: center;
}
.mes_reasoning_header {
  background: transparent; 
  border: 1px solid var(--ins-border); 
  border-radius: 30px; 
  padding: 6px 18px;
  transition: all 0.2s ease;
}
.mes_reasoning_summary:hover .mes_reasoning_header { background: rgba(255, 255, 255, 0.6); }
.mes_reasoning_header_title { font-size: 0 !important; }
.mes_reasoning_header_title::before {
  content: var(--自定义思维链文案); 
  font-size: 13px; 
  color: var(--ins-accent); 
  font-weight: normal; 
}
.mes_reasoning_arrow { font-size: 0 !important; }
.mes_reasoning_arrow::before {
  content: ' ';
  font-size: 16px; 
  color: var(--ins-accent);
  display: inline-block; 
  transition: transform 0.2s ease;
  margin-right: 4px;
}
details[open] .mes_reasoning_arrow::before { transform: rotate(90deg); }
.mes_reasoning {
  margin-top: 10px; 
  padding: 12px 16px;
  background-color: rgba(255, 255, 255, 0.4);
  border-left: 3px solid var(--ins-border); 
  border-radius: 0 8px 8px 0; 
  color: var(--ins-accent); 
  font-size: 14px;
  line-height: 1.6;
}

/* === 九、收藏栏左右滑动查看角色 === */
.hotswap.avatars_inline {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  padding-right: 15px;
  scrollbar-width: none;
}
.hotswap.avatars_inline::-webkit-scrollbar { display: none; }
@media (max-width: 768px) { .hotswap.avatars_inline { overflow: auto; } }

/* 来自s老师，抽屉直角*/
.drawer-content, #extensionTopBar { border-radius: 0 !important; }
